/* ── Google Fonts ─────────────────────────────────────────────────────────── */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Sora:wght@400;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

/* ── Design Tokens ────────────────────────────────────────────────────────── */
:root {
  --bg-base:       #0b0f1a;
  --bg-surface:    #111827;
  --bg-card:       #1a2235;
  --bg-card-hover: #1f2a40;
  --border:        rgba(255,255,255,0.07);
  --border-hover:  rgba(255,255,255,0.14);

  --invest:        #00c896;
  --invest-dim:    rgba(0,200,150,0.1);
  --pass:          #ff4d4f;
  --pass-dim:      rgba(255,77,79,0.1);
  --watch:         #fbbf24;
  --watch-dim:     rgba(251,191,36,0.1);

  --accent:        #6366f1;
  --accent-dim:    rgba(99,102,241,0.12);
  --blue:          #3b82f6;

  --text-primary:  #f1f5f9;
  --text-secondary:#94a3b8;
  --text-muted:    #475569;
}

/* ── Base ─────────────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: 'Inter', system-ui, sans-serif;
  background-color: var(--bg-base);
  color: var(--text-primary);
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
  overflow-x: hidden;
}

/* ── Scrollbar ────────────────────────────────────────────────────────────── */
::-webkit-scrollbar { width: 5px; height: 5px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #334155; border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: #475569; }

/* ── Card Variants ────────────────────────────────────────────────────────── */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 14px;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.card:hover {
  border-color: var(--border-hover);
  box-shadow: 0 4px 24px rgba(0,0,0,0.25);
}

.card-glass {
  background: rgba(26,34,53,0.6);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--border);
  border-radius: 14px;
}

/* ── Stat Card ────────────────────────────────────────────────────────────── */
.stat-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem 1.5rem;
  transition: border-color 0.2s, transform 0.2s, box-shadow 0.2s;
}
.stat-card:hover {
  border-color: var(--border-hover);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
}

/* ── Verdict Colors ───────────────────────────────────────────────────────── */
.verdict-invest { color: var(--invest); }
.verdict-pass   { color: var(--pass); }
.verdict-watch  { color: var(--watch); }

.badge-invest { background: var(--invest-dim); color: var(--invest); border: 1px solid rgba(0,200,150,0.25); }
.badge-pass   { background: var(--pass-dim);   color: var(--pass);   border: 1px solid rgba(255,77,79,0.25); }
.badge-watch  { background: var(--watch-dim);  color: var(--watch);  border: 1px solid rgba(251,191,36,0.25); }

/* ── Tabs ─────────────────────────────────────────────────────────────────── */
.tab-bar {
  display: flex;
  gap: 4px;
  background: var(--bg-surface);
  border-radius: 10px;
  padding: 4px;
  border: 1px solid var(--border);
}
.tab-item {
  flex: 1;
  padding: 0.5rem 1rem;
  border-radius: 7px;
  font-size: 0.8rem;
  font-weight: 600;
  text-align: center;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  color: var(--text-secondary);
  border: none;
  background: transparent;
}
.tab-item.active {
  background: var(--bg-card);
  color: var(--text-primary);
  box-shadow: 0 1px 4px rgba(0,0,0,0.3);
}
.tab-item:hover:not(.active) {
  color: var(--text-primary);
  background: rgba(255,255,255,0.04);
}

/* ── Accordion ────────────────────────────────────────────────────────────── */
.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.25s ease;
  opacity: 0;
}
.accordion-content.open {
  max-height: 1200px;
  opacity: 1;
}

/* ── Progress Steps ───────────────────────────────────────────────────────── */
.step-connector {
  flex: 1;
  height: 2px;
  background: var(--border);
  position: relative;
  overflow: hidden;
}
.step-connector.done {
  background: var(--invest);
}
.step-connector.active::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--invest) 0%, transparent 100%);
  animation: shimmer-line 1.5s infinite;
}
@keyframes shimmer-line {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

/* ── Animations ───────────────────────────────────────────────────────────── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.95); }
  to   { opacity: 1; transform: scale(1); }
}
@keyframes slideRight {
  from { opacity: 0; transform: translateX(-12px); }
  to   { opacity: 1; transform: translateX(0); }
}
@keyframes countUp {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes spin-slow {
  to { transform: rotate(360deg); }
}
@keyframes pulse-ring {
  0%, 100% { opacity: 0.4; transform: scale(1); }
  50% { opacity: 0.8; transform: scale(1.05); }
}
@keyframes gradient-shift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}
@keyframes grid-fade {
  from { opacity: 0; }
  to   { opacity: 0.4; }
}

.animate-fade-up      { animation: fadeUp 0.5s ease-out forwards; }
.animate-fade-in      { animation: fadeIn 0.4s ease-out forwards; }
.animate-scale-in     { animation: scaleIn 0.4s ease-out forwards; }
.animate-slide-right  { animation: slideRight 0.4s ease-out forwards; }
.animate-spin-slow    { animation: spin-slow 4s linear infinite; }
.animate-float        { animation: float 3s ease-in-out infinite; }

/* ── Hero Background Grid ─────────────────────────────────────────────────── */
.hero-grid-bg {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(99,102,241,0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(99,102,241,0.06) 1px, transparent 1px);
  background-size: 40px 40px;
  animation: grid-fade 1s ease-out forwards;
}

.hero-glow {
  position: absolute;
  top: -20%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 400px;
  background: radial-gradient(ellipse, rgba(99,102,241,0.12) 0%, transparent 70%);
  pointer-events: none;
}

/* ── Gradient Text ────────────────────────────────────────────────────────── */
.gradient-text {
  background: linear-gradient(135deg, #f1f5f9 0%, #94a3b8 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.gradient-text-accent {
  background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 50%, #06b6d4 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.gradient-text-invest {
  background: linear-gradient(135deg, #00c896, #10b981);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ── Search Bar ───────────────────────────────────────────────────────────── */
.search-wrapper {
  position: relative;
}
.search-wrapper::before {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(99,102,241,0.5), rgba(139,92,246,0.5), rgba(6,182,212,0.5));
  opacity: 0;
  transition: opacity 0.3s;
  z-index: 0;
}
.search-wrapper:focus-within::before {
  opacity: 1;
}

/* ── Ticker Badge ─────────────────────────────────────────────────────────── */
.ticker-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(99,102,241,0.15);
  border: 1px solid rgba(99,102,241,0.3);
  color: #818cf8;
  border-radius: 6px;
  padding: 3px 10px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.75rem;
  font-weight: 500;
}

/* ── Confidence Ring ──────────────────────────────────────────────────────── */
.confidence-ring {
  transition: stroke-dashoffset 1.2s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Metric Pill ──────────────────────────────────────────────────────────── */
.metric-pill-positive { background: rgba(0,200,150,0.1); color: #00c896; }
.metric-pill-negative { background: rgba(255,77,79,0.1);  color: #ff4d4f; }
.metric-pill-neutral  { background: rgba(148,163,184,0.1); color: #94a3b8; }

/* ── Button Variants ──────────────────────────────────────────────────────── */
.btn-primary {
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: white;
  border: none;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s, transform 0.15s, box-shadow 0.2s;
  box-shadow: 0 4px 14px rgba(99,102,241,0.3);
}
.btn-primary:hover:not(:disabled) {
  opacity: 0.9;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(99,102,241,0.4);
}
.btn-primary:active:not(:disabled) { transform: scale(0.97); }
.btn-primary:disabled { opacity: 0.4; cursor: not-allowed; }

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.btn-ghost:hover {
  background: rgba(255,255,255,0.05);
  color: var(--text-primary);
  border-color: var(--border-hover);
}

/* ── Section Label ────────────────────────────────────────────────────────── */
.section-label {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
}

/* ── Divider ──────────────────────────────────────────────────────────────── */
.divider {
  border: none;
  border-top: 1px solid var(--border);
  margin: 0;
}

/* ── Live Dot ─────────────────────────────────────────────────────────────── */
.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--invest);
  animation: pulse-ring 2s ease-in-out infinite;
}

/** @type {import('tailwindcss').Config} */
export default {
  content: [
    './index.html',
    './src/**/*.{js,ts,jsx,tsx}',
  ],
  theme: {
    extend: {
      fontFamily: {
        sans:    ['Inter', 'system-ui', 'sans-serif'],
        display: ['Sora', 'Inter', 'sans-serif'],
        mono:    ['JetBrains Mono', 'monospace'],
      },
      colors: {
        bg: {
          base:    '#0b0f1a',
          surface: '#111827',
