function ConfidenceRing({ confidence, color }) {
  const [animated, setAnimated] = useState(0);
  const radius = 38;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (animated / 100) * circumference;

  useEffect(() => {
    const t = setTimeout(() => setAnimated(confidence), 200);
    return () => clearTimeout(t);
  }, [confidence]);

  const getLabel = (c) => c >= 75 ? 'High' : c >= 50 ? 'Medium' : 'Low';

  return (
    <div className="flex flex-col items-center gap-3">
      <div className="relative flex items-center justify-center w-28 h-28">
        <svg className="w-28 h-28 -rotate-90" viewBox="0 0 92 92">
          <circle cx="46" cy="46" r={radius} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="6" />
          <circle
            cx="46" cy="46" r={radius}
            fill="none"
            stroke={color}
            strokeWidth="6"
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={offset}
            className="confidence-ring"
          />
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className="text-2xl font-bold font-display" style={{ color: 'var(--text-primary)' }}>{confidence}</span>
          <span className="text-[9px] font-bold uppercase tracking-wider" style={{ color: 'var(--text-muted)' }}>/ 100</span>
        </div>
      </div>
      <div className="text-center">
        <p className="text-xs font-semibold" style={{ color: 'var(--text-secondary)' }}>AI Confidence</p>
        <p className="text-xs font-bold" style={{ color: color }}>{getLabel(confidence)} Conviction</p>
      </div>
    </div>
  );
}

function MetricCard({ icon, label, value, colorStyle }) {
