                  <span className="ticker-badge">🔒 Private</span>
                )}
                <span className="text-xs px-2 py-0.5 rounded-full" style={{ background: 'rgba(255,255,255,0.05)', color: 'var(--text-muted)' }}>
                  AI Research Report
