          colorStyle={{ color: cfg.cssVar }}
        />
        <MetricCard
          icon="📈"
          label="Sentiment"
          value={mSentiment}
          colorStyle={{ color: sentimentColor }}
        />
        <MetricCard
          icon="🏆"
          label="Market Position"
          value={mMarketPos}
          colorStyle={{ color: 'var(--blue)' }}
        />
        <MetricCard
          icon="💰"
          label="Financial Health"
