49: ::-webkit-scrollbar { width: 5px; height: 5px; }
50: ::-webkit-scrollbar-track { background: transparent; }
51: ::-webkit-scrollbar-thumb { background: #334155; border-radius: 4px; }
52: ::-webkit-scrollbar-thumb:hover { background: #475569; }
