59:   transition: border-color 0.2s, box-shadow 0.2s;
60: }
61: .card:hover {
62:   border-color: var(--border-hover);
63:   box-shadow: 0 4px 24px rgba(0,0,0,0.25);
64: }
65: 
66: .card-glass {
67:   background: rgba(26,34,53,0.6);
68:   backdrop-filter: blur(12px);
69:   -webkit-backdrop-filter: blur(12px);
70:   border: 1px solid var(--border);
71:   border-radius: 14px;
72: }
73: 
74: /* ── Stat Card ────────────────────────────────────────────────────────────── */
75: .stat-card {
